#include "version_autogenerated.h"
#include "config.h"

/* called by stage1 */
#if defined(CONFIG_ARCH_ARM_SIRIUS) || defined(CONFIG_ARCH_ARM_CANOPUS) || defined(CONFIG_ARCH_ARM_VEGA)
#define OTP_CON_REG		(*(volatile unsigned int *)(REG_BASE_OTP + 0x0000))
#define OTP_STA_REG		(*(volatile unsigned int *)(REG_BASE_OTP + 0x0004))
#define OTP_CFG_DATA0_REG	(*(volatile unsigned int *)(REG_BASE_OTP + 0x0008))
#define OTP_CFG_DATA1_REG	(*(volatile unsigned int *)(REG_BASE_OTP + 0x000C))
#define OTP_CFG_DATA2_REG	(*(volatile unsigned int *)(REG_BASE_OTP + 0x0010))
#define OTP_CFG_DATA3_REG	(*(volatile unsigned int *)(REG_BASE_OTP + 0x0014))

unsigned char otp_read_simple(unsigned int address)
{
	unsigned int otp_con_reg;
	unsigned char dat;

	otp_con_reg = ((address) << 3) & 0xffff;

	while(OTP_STA_REG & 0x100);
	OTP_CON_REG =  otp_con_reg | (0x1 << 30);
	OTP_CON_REG =  otp_con_reg;
	while(!(OTP_STA_REG & 0x200));
	dat = (unsigned char)(OTP_STA_REG & 0xff);

	return dat;
}
#elif defined (CONFIG_ARCH_CKMMU_TAURUS) || defined (CONFIG_ARCH_CKMMU_GEMINI) || defined(CONFIG_ARCH_CKMMU_CYGNUS) || defined(CONFIG_ARCH_CKMMU_SCORPIO) \
	|| defined(CONFIG_ARCH_CKMMU_SCORPIO_TAURUS)
#define OTP_CON_REG         (*(volatile unsigned int*)(REG_BASE_OTP + 0x80 - GX_REG_VIRTUAL_BASE1))  // OTP control register
#define OTP_CFG_REG         (*(volatile unsigned int*)(REG_BASE_OTP + 0x84 - GX_REG_VIRTUAL_BASE1))  // OTP config register
#define OTP_STA_REG         (*(volatile unsigned int*)(REG_BASE_OTP + 0x88 - GX_REG_VIRTUAL_BASE1))  // OTP state register
#define OTP_CON_MMU_REG         (*(volatile unsigned int*)(REG_BASE_OTP + 0x80))  // OTP control register
#define OTP_CFG_MMU_REG         (*(volatile unsigned int*)(REG_BASE_OTP + 0x84))  // OTP config register
#define OTP_STA_MMU_REG         (*(volatile unsigned int*)(REG_BASE_OTP + 0x88))  // OTP state register

#define DELAY_LOOP   100

unsigned char otp_read_simple(unsigned int address)
{
	int i;
	volatile unsigned int j;
	unsigned int otp_con_reg;
	unsigned char dat;

	otp_con_reg = 0x00000000; // set all control signals to be invalid, address to 0x1800(default)
	while (!(OTP_STA_REG & (1<<10))); // check if OTP Controller is ready
	otp_con_reg = (0x7ff & (address+i))<<3;  // start address
	while (OTP_STA_REG & 0x100); // check if OTP Controller is busy now; 1 for busy
	OTP_CON_REG = otp_con_reg | (0x1 << 14); // set READEN
	j=DELAY_LOOP;
	while (j--);
	OTP_CON_REG &= ~(0x1 << 14); // clear READEN
	while (!(OTP_STA_REG & 0x200)); // chekc if OTP data is ready
	dat = (unsigned char)(OTP_STA_REG & 0xFF);
	OTP_CON_REG = 0x00000000; // set all control signals to be invalid, address to 0x1800(default)

	return dat;
}

unsigned char otp_read_simple_mmu(unsigned int address)
{
	int i;
	volatile unsigned int j;
	unsigned int otp_con_reg;
	unsigned char dat;

	otp_con_reg = 0x00000000; // set all control signals to be invalid, address to 0x1800(default)
	while (!((OTP_STA_MMU_REG) & (1<<10))); // check if OTP Controller is ready
	otp_con_reg = (0x7ff & (address+i))<<3;  // start address
	while (OTP_STA_MMU_REG & 0x100); // check if OTP Controller is busy now; 1 for busy
	OTP_CON_MMU_REG = otp_con_reg | (0x1 << 14); // set READEN
	j=DELAY_LOOP;
	while (j--);
	OTP_CON_MMU_REG &= ~(0x1 << 14); // clear READEN
	while (!(OTP_STA_MMU_REG & 0x200)); // chekc if OTP data is ready
	dat = (unsigned char)(OTP_STA_MMU_REG & 0xFF);
	OTP_CON_MMU_REG = 0x00000000; // set all control signals to be invalid, address to 0x1800(default)

	return dat;
}

#endif

unsigned int otp_read_simple_word(unsigned int address)
{
	unsigned int result=0;
	unsigned int i;

	for(i = 0; i < 4; i++) {
		result >>= 8;
		result |= ((unsigned int)otp_read_simple(address+i))<<24;
	}

	return result;
}
